{
  "conversations": [
    {
      "title": "Accept or decline a dance",
      "lines": [
        {
          "speaker": "partner",
          "text": "Do you want to dance?"
        },
        {
          "speaker": "you",
          "text": "I'd love to."
        },
        {
          "speaker": "you",
          "text": "I don't know how to dance salsa.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "I can teach you."
        },
        {
          "speaker": "you",
          "text": "Let's do it."
        },
        {
          "speaker": "you",
          "text": "Maybe next time.",
          "or": true
        }
      ],
      "vocab": [
        "dance",
        "learn",
        "teach",
        "love",
        "next"
      ]
    },
    {
      "title": "Compliment someone's dancing",
      "lines": [
        {
          "speaker": "you",
          "text": "You're a great dancer."
        },
        {
          "speaker": "partner",
          "text": "Thank you so much."
        },
        {
          "speaker": "you",
          "text": "I love your moves."
        },
        {
          "speaker": "partner",
          "text": "You're doing great too."
        },
        {
          "speaker": "you",
          "text": "Thanks for the dance."
        }
      ],
      "vocab": [
        "dancer",
        "move",
        "great",
        "fun",
        "good"
      ]
    },
    {
      "title": "Chat between songs",
      "lines": [
        {
          "speaker": "partner",
          "text": "Do you come here often?"
        },
        {
          "speaker": "you",
          "text": "This is my first time."
        },
        {
          "speaker": "you",
          "text": "I come here every week.",
          "or": true
        },
        {
          "speaker": "partner",
          "text": "How do you like the music?"
        },
        {
          "speaker": "you",
          "text": "The band is amazing."
        },
        {
          "speaker": "partner",
          "text": "They always play great songs."
        }
      ],
      "vocab": [
        "music",
        "band",
        "song",
        "time",
        "week",
        "play"
      ]
    }
  ]
}
